Method.Source:
      /// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();
    if (ret == true && this.table() == tableNum(smmBusRelTable))
    {
        FormRun   formRun = this.formRun();
        FormDataSource      logPostalAddrDS = formRun.dataSource('LogisticsPostalAddress');

        if (logPostalAddrDS)
        {
            LogisticsPostalAddress          logisticsPostalAddress = logPostalAddrDS.cursor();
            if(logisticsPostalAddress.City == '' || logisticsPostalAddress.CountryRegionId == '' || logisticsPostalAddress.Street == '' || logisticsPostalAddress.ZipCode == '')
            {
                ret = checkFailed("@NDX:NXAAdressNotFull");
            }
        }

        FormDataSource              phoneDS = formRun.dataSource('LogisticsElectronicAddressBusinessPhone');
        if (phoneDS)
        {
            LogisticsElectronicAddress  phone   = phoneDS.cursor();
            if (phone.Locator ==  '')
            {
                ret = checkFailed("@NDX:NXAMissedPhone");
            }
        }


    }
    if (ret == true && this.table() == tableNum(ContactPerson))
    {
        FormRun   formRun = this.formRun();
        FormDataSource      dirPartyPersonDS = formRun.dataSource('DirPartyTable_DirPerson');

        if (dirPartyPersonDS)
        {
            DirPerson   dirPerson = dirPartyPersonDS.cursor();
            if (dirPerson.PersonalTitle == 0)
            {
                ret = checkFailed("@NDX:NXAMissedTitle");
            }
        }
    }

    return  ret;
}

/// <summary>
/// designed from AVA
/// </summary>
public void written()
{
    ContactPerson   locContactPerson;
    smmBusRelTable  locsmmBusRelTable;

    next written();

    switch (this.table())
    {
        case tableNum(ContactPerson):
            locContactPerson = this.cursor();
            break;

        case tableNum(smmBusRelTable):
            locsmmBusRelTable = this.cursor();
            locsmmBusRelTable.AVAafterInsert();
            break;   

        default:
            warning(strFmt("@SYS73692", tableId2Name(this.table())));

    }
    element.refreshCaller();
}
